<?php require 'config.php'; $msg='';$orders=$pdo->query('SELECT o.order_id,b.name buyer,p.name produce,o.quantity,o.status,s.quantity_available FROM orders o JOIN buyers b ON o.buyer_id=b.buyer_id JOIN produce p ON o.produce_id=p.produce_id LEFT JOIN stock s ON s.produce_id=p.produce_id WHERE o.status="Pending" ORDER BY o.order_id')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){ $oid=(int)($_POST['order_id']??0);$pdo->beginTransaction();$q=$pdo->prepare('SELECT o.produce_id,o.quantity,o.status,s.quantity_available FROM orders o JOIN stock s ON s.produce_id=o.produce_id WHERE o.order_id=? FOR UPDATE');$q->execute([$oid]);$r=$q->fetch();if($r&&$r['status']==='Pending'&&$r['quantity_available']>=$r['quantity']){$pdo->prepare('UPDATE stock SET quantity_available=quantity_available-? WHERE produce_id=?')->execute([$r['quantity'],$r['produce_id']]);$pdo->prepare('INSERT INTO dispatches(order_id,dispatch_date,status) VALUES(?,CURDATE(),"Dispatched")')->execute([$oid]);$pdo->prepare('UPDATE orders SET status="Dispatched" WHERE order_id=?')->execute([$oid]);$msg='Dispatch recorded and stock deducted.';}else{$msg='Dispatch rejected: order not pending or stock insufficient.';}$pdo->commit();}
$hist=$pdo->query('SELECT d.dispatch_id,d.order_id,d.dispatch_date,d.status FROM dispatches d ORDER BY d.dispatch_id DESC')->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><title>Dispatches</title><link rel="stylesheet" href="style.css"></head><body><header><h1>Dispatches</h1><nav><a href="index.php">Dashboard</a><a href="farmers.php">Farmers</a><a href="deliveries.php">Deliveries</a><a href="orders.php">Orders</a><a href="reports.php">Reports</a></nav></header><main><h2>Pending orders</h2><?=htmlspecialchars($msg)?><table><tr><th>Order</th><th>Buyer</th><th>Produce</th><th>Qty</th><th>Stock</th><th>Action</th></tr><?php foreach($orders as $o):?><tr><td><?=$o['order_id']?></td><td><?=htmlspecialchars($o['buyer'])?></td><td><?=htmlspecialchars($o['produce'])?></td><td><?=$o['quantity']?></td><td><?=$o['quantity_available']?></td><td><form method="post"><input type="hidden" name="order_id" value="<?=$o['order_id']?>"><button>Dispatch</button></form></td></tr><?php endforeach;?></table><h2>Dispatch history</h2><table><tr><th>Dispatch ID</th><th>Order ID</th><th>Date</th><th>Status</th></tr><?php foreach($hist as $h):?><tr><td><?=$h['dispatch_id']?></td><td><?=$h['order_id']?></td><td><?=$h['dispatch_date']?></td><td><?=htmlspecialchars($h['status'])?></td></tr><?php endforeach;?></table></main></body></html>
